import{Gn as rg,Mn as og,Nn as ol,R as LC,U as Mi,Vt as cT,sr as vI}from"./chunk-B3eT0c-t.js";import"./chunk-Cv7FIPju.js";import{d as si,u as ea}from"./main-FXCFYKB6.js";import{t as Oe}from"./chunk-BgMHGG4v.js";import{a as j,i as _,n as I,o as k,r as T,t as F}from"./chunk-CmXRFFe9.js";var y=class l{static ɵfac=function(o){return new(o||l)};static ɵcmp=cT({type:l,selectors:[[`projects-page`]],decls:115,vars:8,consts:[[1,`page-container`],[`routerLink`,`/css-injection`],[`imgurId`,`GVJ06OK`,`alt`,`hackerman meme image from Kung Fury`,3,`preventDialogOpening`],[`routerLink`,`/flip-dot-display`],[`loading`,`lazy`,`imgurId`,`wFl4yZp`,`alt`,`A flipdot panel with the text 'hack the planet' written in white flip dots`,3,`preventDialogOpening`],[`routerLink`,`/neon-sign`],[`loading`,`lazy`,`imgurId`,`7oWPc71`,`alt`,`A fake neon sign made from blue, yellow, and red LED strips in diffuser tubing`,3,`preventDialogOpening`],[`routerLink`,`/altimeter`],[`href`,`https://www.industrialalchemy.org/storearticleview.php?item=113`,`target`,`_blank`],[`loading`,`lazy`,`src`,`https://www.industrialalchemy.org/media2/store/store1/alphaminitron1.jpg`,`alt`,`closeup of a 16 segment minitron display with all tungsten filament segments brightly lit up`],[`routerLink`,`/qr/about`],[`loading`,`lazy`,`imgurId`,`iFGwWLA`,`alt`,`a forearm prominently displaying a tattoo of a black QR code`,3,`preventDialogOpening`],[`routerLink`,`/smart-pay-watch`],[`loading`,`lazy`,`imgurId`,`WboU1Qg`,`alt`,`a casio digital watch opened up to show custom hardware added around the stock clock element`,3,`preventDialogOpening`],[`routerLink`,`/mountainboard`],[`loading`,`lazy`,`imgurId`,`MCgCxjL`,`alt`,`a mountainboard sitting in dirt pointed downhill towards a large dirt ramp`,3,`preventDialogOpening`],[`routerLink`,`/dot-matrix-watch`],[`href`,`https://www.industrialalchemy.org/articleview.php?item=750`,`target`,`_blank`],[`href`,`https://github.com/blakewilliams1/dot-matrix-watch-2`,`target`,`_blank`],[`href`,`https://cdn.hackaday.io/files/254581089195072/hdsp-2000.pdf`,`target`,`_blank`],[`loading`,`lazy`,`imgurId`,`qUIIJmQ`,`alt`,`a dot matrix display plugged into a prototyping breadboard, illuminating the characters '0123'`,3,`preventDialogOpening`],[`routerLink`,`/nixie-watch`],[`href`,`http://www.cathodecorner.com/nixiewatch/firmware/firmware.html`,`target`,`_blank`],[`loading`,`lazy`,`imgurId`,`dHJe2YO`,`alt`,`a wrist prominently displaying a custom watch made with four nixie tubes lit up showing the current time`,3,`preventDialogOpening`]],template:function(o,x){o&1&&(Mi(0,`div`,0)(1,`mat-card`,1)(2,`mat-card-header`)(3,`mat-card-title`),LC(4,`CSS Injections for Websites`),ol(),Mi(5,`mat-card-subtitle`),LC(6,`The internet how it should be`),ol()(),Mi(7,`mat-card-content`)(8,`p`),LC(9,` A nice and concise set of CSS injections I add to specific websites for better browsing experience. `),ol(),og(10,`img`,2),ol()(),Mi(11,`mat-card`,3)(12,`mat-card-header`)(13,`mat-card-title`),LC(14,`Flip Dot Wall Project`),ol(),Mi(15,`mat-card-subtitle`),LC(16,`Like old-school train displays, but better`),ol()(),Mi(17,`mat-card-content`)(18,`p`),LC(19,` An old wall of flip dots at work fell into disrepair, and the panels were being parted out. I was able to snag a few of them and recreate the wall in a miniature version! It even uses a depth camera to show your silhouette in real time as you move in front of it like the original. `),ol(),og(20,`img`,4),ol()(),Mi(21,`mat-card`,5)(22,`mat-card-header`)(23,`mat-card-title`),LC(24,`Faux Neon Sign Art`),ol(),Mi(25,`mat-card-subtitle`),LC(26,`neon signs without glass blowing`),ol()(),Mi(27,`mat-card-content`)(28,`p`),LC(29,` I found some art online that inspired me to try out making faux neon signs out of led strips tucked inside of diffuser tubing. The end result speaks for itself! `),ol(),og(30,`img`,6),ol()(),Mi(31,`mat-card`,7)(32,`mat-card-header`)(33,`mat-card-title`),LC(34,`16 Segment Minitron Altimeter`),ol(),Mi(35,`mat-card-subtitle`),LC(36,`falling with style`),ol()(),Mi(37,`mat-card-content`)(38,`p`),LC(39,` The altimeter is a must have instrument every time you go skydiving, so why not make it cool? I savaged several `),Mi(40,`a`,8),LC(41,`KW-105AL displays`),ol(),LC(42,` from avionics equipment an the good ol' BMP280 barometer to make an altimeter with.`),og(43,`br`),LC(44,` Finding even 4 of these displays `),Mi(45,`i`),LC(46,`anywhere`),ol(),LC(47,` online literally took months of scouring. `),ol(),og(48,`img`,9),ol()(),Mi(49,`mat-card`,10)(50,`mat-card-header`)(51,`mat-card-title`),LC(52,`QR Code Tattoo`),ol(),Mi(53,`mat-card-subtitle`),LC(54,`not permanent (yet)`),ol()(),Mi(55,`mat-card-content`)(56,`p`),LC(57,` The QR code goes to qrtatt.ooo, and can do some very fancy stuff! Click the link in the upper right to go to the full page I dedicated to talking about the tattoo. `),ol(),og(58,`img`,11),ol()(),Mi(59,`mat-card`,12)(60,`mat-card-header`)(61,`mat-card-title`),LC(62,`Smart Pay Casio Watch`),ol(),Mi(63,`mat-card-subtitle`),LC(64,`[hiatus]`),ol()(),Mi(65,`mat-card-content`)(66,`p`),LC(67,` I like the tap-to-pay features of smart watches, but don't want a fully featured smart watch that needs to be recharged every single day to work. Now that contactless payment via NFC chips is much more common, I wanted to make my own ultra lightweight contactless payment watch. I attempted to make it with favorite cheap digital watch - the Casio A168WEM, a custom NFC antenna I had printed on a flex PCB from Oshpark, and a NFC chip that I got by melting down one of my credit cards in acetone.`),og(68,`br`),LC(69,` Outside of the watch, the NFC chip and custom antenna worked like a charm!! However, I get too much parasitic capacitance or other interference when nestled in the digital watch case. I'll need to figure this out to solve it and call it done. `),ol(),og(70,`img`,13),ol()(),Mi(71,`mat-card`,14)(72,`mat-card-header`)(73,`mat-card-title`),LC(74,`Electric Mountainboard`),ol(),Mi(75,`mat-card-subtitle`),LC(76,`very stoked`),ol()(),Mi(77,`mat-card-content`)(78,`p`),LC(79,` A road bike is to a mountain bike, as a skateboard is to a mountainboard. Their height of popularity was in the early 2000's along with the X-games. Some compare it to the sensation of snowboarding, but like most analogies it's a little bit of a stretch.`),og(80,`br`),LC(81,` This was a major project where I learned about good battery design, some machining skills, and a lot of patience. `),ol(),og(82,`img`,15),ol()(),Mi(83,`mat-card`,16)(84,`mat-card-header`)(85,`mat-card-title`),LC(86,`Dot Matrix Watch`),ol(),Mi(87,`mat-card-subtitle`),LC(88,`[hiatus]`),ol()(),Mi(89,`mat-card-content`)(90,`p`),LC(91,` Wanting to make another watch after finishing the nixie tube watch, I decided to try working with some `),Mi(92,`a`,17),LC(93,`retro dot matrix displays`),ol(),LC(94,`. These are REALLY neat to look at if you can get your hands on them. They're very early gallium-phosphate LEDs; the only application I've seen them used in are for commercial airplane cockpit displays. Because these were used in avionics, they are ceramic case-bodies and the top layer is sapphire. I was able to write `),Mi(95,`a`,18),LC(96,`these display drivers`),ol(),LC(97,` for it based on `),Mi(98,`a`,19),LC(99,`these xerox scans`),ol(),LC(100,` of old datasheets from the 1970's. `),ol(),og(101,`img`,20),ol()(),Mi(102,`mat-card`,21)(103,`mat-card-header`)(104,`mat-card-title`),LC(105,`Nixie Tube Wrist Watch`),ol(),Mi(106,`mat-card-subtitle`),LC(107,`Check the divergence!`),ol()(),Mi(108,`mat-card-content`)(109,`p`),LC(110,` This was one of my first exposures to hardware design beyond simple arduino proto boards that drove small motors or read from simple sensors. I heavily based my schematic off of an existing one I found online by `),Mi(111,`a`,22),LC(112,`David Forbes`),ol(),LC(113,`. The main difference is that mine uses four IN-17 nixie tubes instead of just two B5870L tubes. I accounted for this doubling of tubes by swapping out his PIC18LF22SS with an atmega324pb, which has around 30-ish GPIO pins. I directly drove every filament in use with a GPIO pin and a darlington transistor. As this was my first 'major' hardware project, I didn't want to deal with extra IC components like a serial to parallel shift register to complicate it any more. `),ol(),og(114,`img`,23),ol()()()),o&2&&(vI(10),rg(`preventDialogOpening`,!0),vI(10),rg(`preventDialogOpening`,!0),vI(10),rg(`preventDialogOpening`,!0),vI(28),rg(`preventDialogOpening`,!0),vI(12),rg(`preventDialogOpening`,!0),vI(12),rg(`preventDialogOpening`,!0),vI(19),rg(`preventDialogOpening`,!0),vI(13),rg(`preventDialogOpening`,!0))},dependencies:[T,I,F,k,j,_,Oe,ea,si],styles:[`mat-card[_ngcontent-%COMP%]{cursor:pointer;margin:20px 5%;max-width:800px}mat-card-title[_ngcontent-%COMP%]{color:#fff;font-weight:700}.page-container[_ngcontent-%COMP%]{margin:0 auto;width:fit-content}[_nghost-%COMP%]{display:block;padding-bottom:20px}.no-underline[_ngcontent-%COMP%]{text-decoration:none}img[_ngcontent-%COMP%]{width:100%}`]})};export{y as ProjectsPage};